import { useEffect, useState } from 'react'

/**
 * Loads the precomputed DRKG scene written by `frontend/scripts/drkg_scene.py`
 * into `public/drkg/`. Nothing here computes embeddings: positions are a PCA-3
 * projection of the 400-d TransE vectors, distances are the true 400-d L2.
 */

const BASE = '/drkg/'

export type Vec3 = [number, number, number]

export type DrkgGene = {
  symbol: string
  id: string
  row: number
  pos: Vec3
  /** Projection of e[gene] − r[target]. PCA is linear, so the arrow pos → query is exact. */
  query: Vec3
  targetEdges: number
  alsEdge: string | null
}

export type DrkgMatch = {
  rank: number
  id: string
  row: number
  name: string
  pos: Vec3
  /** True 400-d L2 from the profile's query. */
  distance: number
  viaGene: string
  directEdge: boolean
}

export type DrkgProfile = {
  lane: number
  name: string
  genes: DrkgGene[]
  unresolved: string[]
  matches: DrkgMatch[]
  edges: { from: number; to: number; rel: string }[]
}

export type DrkgScene = {
  meta: {
    model: string
    entities: number
    projection: string
    explainedVariance: number[]
    relation: string
    formula: string
    universe: number
    topK: number
  }
  types: { name: string; count: number }[]
  als: { id: string; row: number; pos: Vec3; label: string }
  profiles: DrkgProfile[]
  handWritten: { drug: string; lane: number; source: string; id: string | null; rank: number | null; distance: number | null }[]
}

export type DrkgData = { scene: DrkgScene; positions: Float32Array; types: Uint8Array }

async function get(path: string) {
  const res = await fetch(BASE + path)
  if (!res.ok) throw new Error(`${path}: ${res.status}`)
  return res
}

let data: Promise<DrkgData> | null = null
let names: Promise<Record<string, string>> | null = null

export function loadDrkg() {
  data ??= Promise.all([
    get('scene.json').then((r) => r.json() as Promise<DrkgScene>),
    get('points.bin').then((r) => r.arrayBuffer()),
    get('types.bin').then((r) => r.arrayBuffer()),
  ]).then(([scene, p, t]) => ({ scene, positions: new Float32Array(p), types: new Uint8Array(t) }))
  data.catch(() => (data = null)) // let a later mount retry
  return data
}

/** Hover labels for every entity; ~0.5 MB, so only fetched on first hover. */
export function loadNames() {
  names ??= get('names.json').then((r) => r.json())
  names.catch(() => (names = null))
  return names
}

export function useDrkg() {
  const [state, setState] = useState<{ data: DrkgData | null; error: string | null }>({ data: null, error: null })
  useEffect(() => {
    let live = true
    loadDrkg().then(
      (data) => live && setState({ data, error: null }),
      (e: Error) => live && setState({ data: null, error: e.message }),
    )
    return () => {
      live = false
    }
  }, [])
  return state
}

