import { memo, useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react'
import { Canvas, useFrame, useThree, type ThreeEvent } from '@react-three/fiber'
import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { LineSegments2 } from 'three/examples/jsm/lines/LineSegments2.js'
import { LineSegmentsGeometry } from 'three/examples/jsm/lines/LineSegmentsGeometry.js'
import { LineMaterial } from 'three/examples/jsm/lines/LineMaterial.js'
import { Loader2, RotateCcw } from 'lucide-react'
import type { StageStatus } from '@/lib/run-store'
import { cn } from '@/lib/utils'
import { LANE_COLORS } from './lanes'
import { loadNames, useDrkg, type DrkgData, type Vec3 } from './drkg-data'

/**
 * Stage 3, drawn from the real DRKG: every one of the 97k entities as one point
 * cloud (PCA-3 of the 400-d TransE vectors), then, profile by profile, a replay
 * of the two traversals the stage performs:
 *
 *   edges       ALS → the profile's target genes → compounds DRKG links to them
 *               (solid lines: real triples from drkg.tsv)
 *   embeddings  e[gene] − r[target] → query point → nearest compounds by 400-d L2
 *               (dashed lines: vector arithmetic, not graph edges)
 *
 * PCA is linear, so the translation arrows are exact in 3D; the L2 rays are not
 * — near in 400-d need not look near here, which is why every ray is labelled.
 * The timeline is driven by the frame loop from `status`; `done` on mount or
 * prefers-reduced-motion shows the end state.
 */

const LEAD = 0.9 // ALS lights before the first profile
const STEP = 3.3 // profile start spacing
const WIN = 3.7 // one profile's window (overlaps the next by 0.4 s)
const OUTRO = 1.6

// Animation tokens (animate skill): reveals ease out, camera moves ease in-out.
const easeOut = bezier(0.23, 1, 0.32, 1)
const easeInOut = bezier(0.77, 0, 0.175, 1)

const TYPE_COLORS: Record<string, string> = {
  Gene: '#3f97a4',
  Compound: '#c99256',
  Disease: '#c4606d',
  'Biological Process': '#7068b8',
  'Molecular Function': '#8a74b0',
  'Cellular Component': '#6d82a3',
  Pathway: '#4f9466',
  'Side Effect': '#5d6c88',
  Atc: '#a58058',
}
const OTHER_COLOR = '#56637a'
const ALS_COLOR = '#ffc7cf'

type Seg = { a: Vec3; b: Vec3; color: THREE.Color; start: number; dur: number; lane: number; settle: number }
type Dot = { pos: Vec3; color: THREE.Color; size: number; shape: number; start: number; lane: number; settle: number; end: number }
type Label = { pos: THREE.Vector3; lane: number; node: ReactNode; opacity: (t: number, focus: number | null) => number }

/* ---------------------------------------------------------------- helpers -- */

function bezier(x1: number, y1: number, x2: number, y2: number) {
  return (x: number) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    let t = x
    for (let i = 0; i < 8; i++) {
      const cx = 3 * x1 * t * (1 - t) ** 2 + 3 * x2 * t * t * (1 - t) + t ** 3 - x
      if (Math.abs(cx) < 1e-5) break
      const dx = 3 * x1 * (1 - t) ** 2 + 6 * (x2 - x1) * t * (1 - t) + 3 * (1 - x2) * t * t
      t = Math.min(1, Math.max(0, t - cx / (dx || 1e-6)))
    }
    return 3 * y1 * t * (1 - t) ** 2 + 3 * y2 * t * t * (1 - t) + t ** 3
  }
}

const ramp = (t: number, a: number, b: number) => Math.min(1, Math.max(0, (t - a) / (b - a)))
/** 1 inside [a, b], easing in over `fade` before a and out after b. */
const window_ = (t: number, a: number, b: number, fade = 0.35) => ramp(t, a, a + fade) * (1 - ramp(t, b, b + fade))
const lighten = (hex: string, k: number) => new THREE.Color(hex).lerp(new THREE.Color('#ffffff'), k)
const start = (lane: number) => LEAD + lane * STEP

function useReducedMotion() {
  const [reduce, setReduce] = useState(() => window.matchMedia('(prefers-reduced-motion: reduce)').matches)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduce(mq.matches)
    mq.addEventListener('change', on)
    return () => mq.removeEventListener('change', on)
  }, [])
  return reduce
}

/* ---------------------------------------------------------------- shaders -- */

const POINT_VERT = /* glsl */ `
  attribute vec3 color;
  attribute float aSize;
  attribute float aAlpha;
  attribute float aShape;
  attribute float aType;
  uniform float uPx;
  uniform float uSize;
  uniform float uAlpha;
  uniform float uBoostType;
  uniform float uBoost;
  varying vec3 vColor;
  varying float vAlpha;
  varying float vShape;
  void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    float boost = abs(aType - uBoostType) < 0.5 ? uBoost : 0.0;
    gl_PointSize = aSize * uSize * (1.0 + boost * 0.8) * uPx * (22.0 / -mv.z);
    vColor = color * (1.0 + boost * 1.4);
    vAlpha = aAlpha * uAlpha * (1.0 + boost * 1.2);
    vShape = aShape;
  }
`
const POINT_FRAG = /* glsl */ `
  varying vec3 vColor;
  varying float vAlpha;
  varying float vShape;
  void main() {
    float d = length(gl_PointCoord - 0.5) * 2.0;
    if (d > 1.0) discard;
    float glow = pow(1.0 - d, 2.2);
    float core = smoothstep(0.42, 0.18, d);
    float ring = smoothstep(0.16, 0.0, abs(d - 0.72));
    // 0: glowing disc · 1: hollow ring (query vectors) · 2: disc + ring (ALS)
    float a = vShape < 0.5 ? glow * 0.7 + core * 0.6
            : vShape < 1.5 ? ring + glow * 0.18
            : glow * 0.6 + core * 0.7 + ring * 0.8;
    gl_FragColor = vec4(vColor, a * vAlpha);
  }
`
const FAN_VERT = /* glsl */ `
  attribute float aT;
  attribute float aStart;
  attribute float aLane;
  attribute float aSeed;
  attribute vec3 color;
  uniform float uLane[5];
  varying float vT;
  varying float vStart;
  varying float vSeed;
  varying float vLane;
  varying vec3 vColor;
  void main() {
    vT = aT; vStart = aStart; vSeed = aSeed; vColor = color;
    vLane = uLane[int(aLane + 0.5)];
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`
const FAN_FRAG = /* glsl */ `
  uniform float uTime;
  uniform float uFlow;
  varying float vT;
  varying float vStart;
  varying float vSeed;
  varying float vLane;
  varying vec3 vColor;
  void main() {
    float r = clamp((uTime - vStart) / 0.5, 0.0, 1.0);
    if (vT > r || r <= 0.0) discard;
    float head = exp(-pow((vT - r) * 12.0, 2.0)) * (1.0 - smoothstep(0.9, 1.0, r));
    float flow = exp(-pow((fract(uTime * 0.32 + vSeed) - vT) * 9.0, 2.0)) * uFlow;
    // Bright while its profile is being walked, settles to a faint filament.
    float active = 1.0 - smoothstep(${WIN - 0.2}, ${WIN + 0.6}, uTime - vStart + 0.5);
    float a = (0.1 + active * 0.22) + head * 0.9 + flow * (0.18 + active * 0.3);
    gl_FragColor = vec4(vColor, a * vLane);
  }
`

/* ---------------------------------------------------------- build the run -- */

function build(data: DrkgData) {
  const { scene, positions: P } = data
  const at = (row: number): Vec3 => [P[row * 3], P[row * 3 + 1], P[row * 3 + 2]]
  const profiles = [...scene.profiles].sort((a, b) => a.lane - b.lane)
  const end = start(profiles.length - 1) + WIN + OUTRO

  const dots: Dot[] = [{ pos: scene.als.pos, color: new THREE.Color(ALS_COLOR), size: 15, shape: 2, start: 0.1, lane: -1, settle: 1, end }]
  const solid: Seg[] = []
  const dashed: Seg[] = []
  const cones: { from: Vec3; to: Vec3; color: THREE.Color; start: number; lane: number }[] = []
  const fan: { a: Vec3; b: Vec3; start: number; lane: number; color: THREE.Color }[] = []
  const labels: Label[] = []
  const focus: { target: THREE.Vector3; dist: number }[] = []

  labels.push({
    pos: new THREE.Vector3(...scene.als.pos),
    lane: -1,
    opacity: (t) => ramp(t, 0.2, 0.6),
    node: (
      <span className="rounded-md bg-black/45 px-1.5 py-0.5 font-medium text-white ring-1 ring-white/25">
        ALS <span className="font-normal text-white/60">{scene.als.id.replace('Disease::', '')}</span>
      </span>
    ),
  })

  for (const p of profiles) {
    const s = start(p.lane)
    const c = LANE_COLORS[p.lane % LANE_COLORS.length]
    const bright = lighten(c, 0.35)
    const own = (t: number, f: number | null) => (f === p.lane ? 1 : f !== null ? 0 : window_(t, s, s + WIN + 0.2, 0.4))

    p.genes.forEach((g, gi) => {
      if (g.alsEdge) solid.push({ a: scene.als.pos, b: g.pos, color: bright, start: s + gi * 0.08, dur: 0.55, lane: p.lane, settle: 0.4 })
      dots.push({ pos: g.pos, color: bright, size: 10, shape: 0, start: s + 0.3 + gi * 0.08, lane: p.lane, settle: 0.7, end })
      const a0 = s + 1.4 + gi * 0.15
      dashed.push({ a: g.pos, b: g.query, color: lighten(c, 0.55), start: a0, dur: 0.6, lane: p.lane, settle: 0.35 })
      cones.push({ from: g.pos, to: g.query, color: lighten(c, 0.55), start: a0, lane: p.lane })
      dots.push({ pos: g.query, color: lighten(c, 0.5), size: 13, shape: 1, start: a0 + 0.55, lane: p.lane, settle: 0.6, end })
      labels.push({
        pos: new THREE.Vector3(...g.pos),
        lane: p.lane,
        opacity: own,
        node: <span className="rounded bg-black/40 px-1 font-mono text-[11px] font-medium text-white ring-1" style={{ ['--tw-ring-color' as string]: c }}>{g.symbol}</span>,
      })
    })

    const first = p.genes[0]
    if (first) {
      const mid = new THREE.Vector3(...first.pos).lerp(new THREE.Vector3(...first.query), 0.5)
      labels.push({
        pos: mid,
        lane: p.lane,
        opacity: (t, f) => (f !== null ? 0 : window_(t, s + 1.5, s + 2.7, 0.3)),
        node: (
          <span className="rounded bg-black/55 px-1.5 py-0.5 font-mono text-[11px] text-white">
            e[{first.symbol}] − r[target]
          </span>
        ),
      })
    }

    const matchRows = new Set(p.matches.map((m) => m.row))
    const fanned = new Set<number>()
    p.edges.forEach((e, j) => {
      const st = s + 0.45 + (p.edges.length > 1 ? j / (p.edges.length - 1) : 0) * 0.6
      fan.push({ a: at(e.from), b: at(e.to), start: st, lane: p.lane, color: bright })
      if (!matchRows.has(e.to) && !fanned.has(e.to)) {
        fanned.add(e.to)
        dots.push({ pos: at(e.to), color: bright, size: 4.2, shape: 0, start: st + 0.5, lane: p.lane, settle: 0.4, end })
      }
    })

    const queries = new Map(p.genes.map((g) => [g.symbol, g.query]))
    p.matches.forEach((m, k) => {
      const q = queries.get(m.viaGene) ?? first?.query ?? scene.als.pos
      const r0 = s + 2.1 + k * 0.18
      dashed.push({ a: q, b: m.pos, color: lighten(c, 0.2), start: r0, dur: 0.45, lane: p.lane, settle: 0.25 })
      dots.push({ pos: m.pos, color: lighten(c, 0.45), size: k === 0 ? 15 : 11.5, shape: 0, start: r0 + 0.4, lane: p.lane, settle: k === 0 ? 0.95 : 0.6, end })
      const pop = r0 + 0.4
      labels.push({
        pos: new THREE.Vector3(...m.pos),
        lane: p.lane,
        opacity: (t, f) => {
          const shown = ramp(t, pop, pop + 0.3)
          if (f !== null) return f === p.lane ? shown : 0
          return shown * Math.max(1 - ramp(t, s + WIN + 0.2, s + WIN + 0.6), k === 0 ? 0.9 : 0)
        },
        node: (
          <span className="flex items-baseline gap-1.5 rounded-md bg-black/50 px-1.5 py-0.5 text-white ring-1 ring-white/15">
            {k === 0 ? <span className="size-1.5 self-center rounded-full" style={{ background: c }} aria-hidden /> : null}
            <span className="font-medium">{m.name}</span>
            <span className="font-mono text-[11px] text-white/65 tabular-nums">{m.distance.toFixed(2)}</span>
          </span>
        ),
      })
    })

    // Camera focus: centroid of everything this profile touches.
    const pts = [...p.genes.flatMap((g) => [g.pos, g.query]), ...p.matches.map((m) => m.pos)].map((v) => new THREE.Vector3(...v))
    const target = pts.reduce((acc, v) => acc.add(v), new THREE.Vector3()).divideScalar(Math.max(1, pts.length))
    const radius = pts.reduce((r, v) => Math.max(r, v.distanceTo(target)), 0)
    focus.push({ target, dist: THREE.MathUtils.clamp(radius * 2.3 + 7, 13, 28) })
  }

  return { dots, solid, dashed, cones, fan, labels, focus, end, profiles }
}

type Built = ReturnType<typeof build>

/* ------------------------------------------------------------------ world -- */

type WorldProps = {
  data: DrkgData
  built: Built
  status: StageStatus
  reduce: boolean
  focusLane: number | null
  replay: number
  labelEls: React.RefObject<(HTMLDivElement | null)[]>
  onPhase: (phase: string) => void
  onReveal?: (n: number) => void
  onHover: (h: { row: number; x: number; y: number } | null) => void
}

const World = memo(function World({ data, built, status, reduce, focusLane, replay, labelEls, onPhase, onReveal, onHover }: WorldProps) {
  const { camera, gl, size } = useThree()
  const dpr = gl.getPixelRatio()
  const t = useRef(status === 'done' || reduce ? built.end : 0)
  const guided = useRef(true)
  const lastPhase = useRef('')
  const lastReveal = useRef(-1)
  const laneAlpha = useRef(new Float32Array(5).fill(1))
  const v = useMemo(() => new THREE.Vector3(), [])

  useEffect(() => {
    if (replay === 0) return
    t.current = reduce ? built.end : 0
    guided.current = true
  }, [replay, reduce, built.end])

  useEffect(() => {
    if (reduce) t.current = built.end
  }, [reduce, built.end])

  /* controls */
  const controls = useMemo(() => {
    const c = new OrbitControls(camera, gl.domElement)
    c.enableDamping = true
    c.dampingFactor = 0.08
    c.enablePan = false
    c.minDistance = 5
    c.maxDistance = 46
    c.rotateSpeed = 0.6
    c.addEventListener('start', () => (guided.current = false))
    return c
  }, [camera, gl])
  useEffect(() => () => controls.dispose(), [controls])

  /* background cloud: one Points, static */
  const cloud = useMemo(() => {
    const { scene, positions, types } = data
    const n = positions.length / 3
    const palette = scene.types.map((ty) => new THREE.Color(TYPE_COLORS[ty.name] ?? OTHER_COLOR))
    const color = new Float32Array(n * 3)
    const aType = new Float32Array(n)
    for (let i = 0; i < n; i++) {
      const c = palette[types[i]] ?? palette[0]
      color[i * 3] = c.r
      color[i * 3 + 1] = c.g
      color[i * 3 + 2] = c.b
      aType[i] = types[i]
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(color, 3))
    geo.setAttribute('aType', new THREE.BufferAttribute(aType, 1))
    geo.setAttribute('aSize', new THREE.BufferAttribute(new Float32Array(n).fill(1), 1))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(new Float32Array(n).fill(1), 1))
    geo.setAttribute('aShape', new THREE.BufferAttribute(new Float32Array(n), 1))
    geo.computeBoundingSphere()
    const mat = new THREE.ShaderMaterial({
      vertexShader: POINT_VERT,
      fragmentShader: POINT_FRAG,
      uniforms: {
        uPx: { value: dpr },
        uSize: { value: 2.3 },
        uAlpha: { value: 0.34 },
        uBoostType: { value: scene.types.findIndex((ty) => ty.name === 'Compound') },
        uBoost: { value: 0 },
      },
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    return new THREE.Points(geo, mat)
  }, [data, dpr])

  /* highlights: ALS, genes, query vectors, matches, edge-linked compounds */
  const overlay = useMemo(() => {
    const n = built.dots.length
    const pos = new Float32Array(n * 3)
    const color = new Float32Array(n * 3)
    const shape = new Float32Array(n)
    built.dots.forEach((d, i) => {
      pos.set(d.pos, i * 3)
      color.set([d.color.r, d.color.g, d.color.b], i * 3)
      shape[i] = d.shape
    })
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(color, 3))
    geo.setAttribute('aShape', new THREE.BufferAttribute(shape, 1))
    geo.setAttribute('aType', new THREE.BufferAttribute(new Float32Array(n).fill(-9), 1))
    geo.setAttribute('aSize', new THREE.BufferAttribute(new Float32Array(n), 1))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(new Float32Array(n), 1))
    geo.computeBoundingSphere()
    const mat = new THREE.ShaderMaterial({
      vertexShader: POINT_VERT,
      fragmentShader: POINT_FRAG,
      uniforms: { uPx: { value: dpr }, uSize: { value: 1 }, uAlpha: { value: 1 }, uBoostType: { value: -1 }, uBoost: { value: 0 } },
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    const pts = new THREE.Points(geo, mat)
    pts.renderOrder = 3
    return pts
  }, [built, dpr])

  /* fan: real gene → compound triples, revealed + pulsed in the shader */
  const fan = useMemo(() => {
    const n = built.fan.length
    const pos = new Float32Array(n * 6)
    const color = new Float32Array(n * 6)
    const aT = new Float32Array(n * 2)
    const aStart = new Float32Array(n * 2)
    const aLane = new Float32Array(n * 2)
    const aSeed = new Float32Array(n * 2)
    built.fan.forEach((e, i) => {
      pos.set([...e.a, ...e.b], i * 6)
      color.set([e.color.r, e.color.g, e.color.b, e.color.r, e.color.g, e.color.b], i * 6)
      aT.set([0, 1], i * 2)
      aStart.set([e.start, e.start], i * 2)
      aLane.set([e.lane, e.lane], i * 2)
      const seed = (i * 0.618) % 1
      aSeed.set([seed, seed], i * 2)
    })
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(color, 3))
    geo.setAttribute('aT', new THREE.BufferAttribute(aT, 1))
    geo.setAttribute('aStart', new THREE.BufferAttribute(aStart, 1))
    geo.setAttribute('aLane', new THREE.BufferAttribute(aLane, 1))
    geo.setAttribute('aSeed', new THREE.BufferAttribute(aSeed, 1))
    const mat = new THREE.ShaderMaterial({
      vertexShader: FAN_VERT,
      fragmentShader: FAN_FRAG,
      uniforms: { uTime: { value: 0 }, uFlow: { value: 1 }, uLane: { value: Array.from(laneAlpha.current) } },
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    const lines = new THREE.LineSegments(geo, mat)
    lines.frustumCulled = false
    lines.renderOrder = 1
    return lines
  }, [built])

  /* thick lines: solid = real edges ALS → gene; dashed = vector arithmetic */
  const makeThick = useCallback(
    (segs: Seg[], dashed: boolean) => {
      const geo = new LineSegmentsGeometry()
      geo.setPositions(segs.flatMap((s) => [...s.a, ...s.b]))
      geo.setColors(new Array(segs.length * 6).fill(0))
      const mat = new LineMaterial({
        linewidth: dashed ? 1.6 : 2.2,
        vertexColors: true,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        dashed,
        dashSize: 0.32,
        gapSize: 0.2,
      })
      mat.resolution.set(size.width, size.height)
      const line = new LineSegments2(geo, mat)
      if (dashed) line.computeLineDistances()
      line.frustumCulled = false
      line.renderOrder = 2
      return line
    },
    // resolution is kept current in the frame loop
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  )
  const solid = useMemo(() => makeThick(built.solid, false), [built, makeThick])
  const dashed = useMemo(() => makeThick(built.dashed, true), [built, makeThick])

  /* arrowheads on the translation e[gene] − r */
  const cones = useMemo(() => {
    const geo = new THREE.ConeGeometry(0.13, 0.42, 14)
    geo.translate(0, -0.21, 0) // tip at the origin, so it sits on the query point
    const mat = new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, blending: THREE.AdditiveBlending })
    const mesh = new THREE.InstancedMesh(geo, mat, Math.max(1, built.cones.length))
    mesh.count = built.cones.length
    built.cones.forEach((c, i) => mesh.setColorAt(i, c.color))
    mesh.frustumCulled = false
    mesh.renderOrder = 2
    return mesh
  }, [built])

  useEffect(
    () => () => {
      for (const o of [cloud, overlay, fan, solid, dashed, cones]) {
        o.geometry.dispose()
        ;(o.material as THREE.Material).dispose()
      }
    },
    [cloud, overlay, fan, solid, dashed, cones],
  )

  /* first frame: overview camera */
  useEffect(() => {
    camera.position.set(9, 7, 25)
    controls.target.set(0, 0, 0)
    controls.update()
  }, [camera, controls, replay])

  const m4 = useMemo(() => new THREE.Matrix4(), [])
  const q4 = useMemo(() => new THREE.Quaternion(), [])
  const up = useMemo(() => new THREE.Vector3(0, 1, 0), [])
  const dir = useMemo(() => new THREE.Vector3(), [])
  const tip = useMemo(() => new THREE.Vector3(), [])
  const scl = useMemo(() => new THREE.Vector3(), [])
  const goal = useMemo(() => new THREE.Vector3(), [])

  useFrame((_, rawDt) => {
    const dt = Math.min(rawDt, 0.05)
    if (status !== 'pending' && t.current < built.end) t.current = Math.min(built.end, t.current + dt)
    const time = t.current
    const playing = time < built.end && status !== 'pending'
    const n = built.profiles.length

    // lane dimming for focusLane
    const la = laneAlpha.current
    for (let i = 0; i < 5; i++) {
      const want = focusLane === null ? 1 : focusLane === i ? 1.25 : 0.1
      la[i] += (want - la[i]) * (1 - Math.exp(-dt * 10))
    }
    const laneA = (lane: number) => (lane < 0 ? 1 : la[lane] ?? 1)

    // active profile + phase text
    let active = -1
    for (let i = 0; i < n; i++) if (time >= start(i)) active = i
    let phase = 'DRKG · 97,238 entities'
    if (status !== 'pending') {
      if (time < LEAD) phase = `ALS · ${built.profiles.length ? 'Disease::MESH:D000690' : ''}`
      else if (playing && active >= 0) {
        const p = built.profiles[active]
        const u = time - start(active)
        const genes = p.genes.map((g) => g.symbol).join(' · ')
        phase =
          u < 1.4 ? `${p.name} — walking edges · ${genes}`
          : u < 2.1 ? `${p.name} — e[${p.genes[0]?.symbol ?? 'gene'}] − r[target]`
          : `${p.name} — L2 scan · ${data.scene.meta.universe.toLocaleString()} compounds`
      } else phase = `Done · ${n} profiles · top ${data.scene.meta.topK} by 400-d L2`
    }
    if (phase !== lastPhase.current) {
      lastPhase.current = phase
      onPhase(phase)
    }
    const revealed = built.profiles.filter((p) => time >= start(p.lane) + WIN - 0.3).length
    if (revealed !== lastReveal.current) {
      lastReveal.current = revealed
      onReveal?.(revealed)
    }

    // background: all compounds brighten during each L2 scan
    let boost = 0
    for (let i = 0; i < n; i++) boost = Math.max(boost, window_(time, start(i) + 2.1, start(i) + 3.0, 0.3))
    cloud.material.uniforms.uBoost.value = boost * 0.55
    cloud.material.uniforms.uPx.value = dpr

    // overlay dots
    const sizeA = overlay.geometry.attributes.aSize as THREE.BufferAttribute
    const alphaA = overlay.geometry.attributes.aAlpha as THREE.BufferAttribute
    built.dots.forEach((d, i) => {
      const appear = easeOut(ramp(time, d.start, d.start + 0.35))
      const pop = ramp(time, d.start, d.start + 0.18) * (1 - ramp(time, d.start + 0.18, d.start + 0.6))
      const own = d.lane < 0 ? 1 : 1 - (1 - d.settle) * ramp(time, start(d.lane) + WIN, start(d.lane) + WIN + 0.6)
      const breathe = d.lane < 0 && !reduce ? 1 + 0.08 * Math.sin(performance.now() / 600) : 1
      sizeA.array[i] = d.size * (1 + pop * 0.7) * breathe
      alphaA.array[i] = appear * own * laneA(d.lane)
    })
    sizeA.needsUpdate = true
    alphaA.needsUpdate = true

    // fan lines
    fan.material.uniforms.uTime.value = time
    fan.material.uniforms.uFlow.value = reduce ? 0 : 1
    fan.material.uniforms.uLane.value = Array.from(la)

    // thick lines: grow from a to b, then settle
    for (const [line, segs] of [[solid, built.solid], [dashed, built.dashed]] as const) {
      const g = line.geometry as LineSegmentsGeometry
      const posBuf = (g.attributes.instanceStart as THREE.InterleavedBufferAttribute).data
      const colBuf = (g.attributes.instanceColorStart as THREE.InterleavedBufferAttribute).data
      segs.forEach((s, i) => {
        const r = easeOut(ramp(time, s.start, s.start + s.dur))
        const k = (r > 0 ? 1 : 0) * (1 - (1 - s.settle) * ramp(time, start(s.lane) + WIN, start(s.lane) + WIN + 0.6)) * laneA(s.lane)
        const o = i * 6
        posBuf.array[o + 3] = s.a[0] + (s.b[0] - s.a[0]) * r
        posBuf.array[o + 4] = s.a[1] + (s.b[1] - s.a[1]) * r
        posBuf.array[o + 5] = s.a[2] + (s.b[2] - s.a[2]) * r
        colBuf.array[o] = colBuf.array[o + 3] = s.color.r * k
        colBuf.array[o + 1] = colBuf.array[o + 4] = s.color.g * k
        colBuf.array[o + 2] = colBuf.array[o + 5] = s.color.b * k
      })
      posBuf.needsUpdate = true
      colBuf.needsUpdate = true
      ;(line.material as LineMaterial).resolution.set(size.width, size.height)
    }

    // arrowheads ride the tip of each translation
    built.cones.forEach((c, i) => {
      const s = built.dashed.find((d) => d.start === c.start && d.lane === c.lane)
      const r = easeOut(ramp(time, c.start, c.start + (s?.dur ?? 0.6)))
      dir.set(c.to[0] - c.from[0], c.to[1] - c.from[1], c.to[2] - c.from[2])
      tip.set(c.from[0], c.from[1], c.from[2]).addScaledVector(dir, r)
      q4.setFromUnitVectors(up, dir.normalize())
      const k = r > 0 ? laneA(c.lane) : 0
      scl.setScalar(k > 0.02 ? Math.min(1, k) : 0.0001)
      m4.compose(tip, q4, scl)
      cones.setMatrixAt(i, m4)
    })
    cones.instanceMatrix.needsUpdate = true

    // camera guidance (until the user grabs the controls)
    controls.autoRotate = !reduce
    controls.autoRotateSpeed = playing ? 0.45 : 0.3
    if (guided.current) {
      const f = playing && time >= LEAD && active >= 0 && time < built.end - OUTRO ? built.focus[active] : null
      goal.copy(f ? f.target : new THREE.Vector3())
      const want = f ? f.dist : 27
      const k = 1 - Math.exp(-dt * 1.4)
      controls.target.lerp(goal, k)
      const off = camera.position.clone().sub(controls.target)
      const len = off.length()
      off.setLength(len + (want - len) * easeInOut(Math.min(1, k * 1.6)))
      camera.position.copy(controls.target).add(off)
    }
    controls.update(dt)

    // DOM labels: transform + opacity only, no layout reads
    const els = labelEls.current
    built.labels.forEach((l, i) => {
      const el = els?.[i]
      if (!el) return
      const op = l.opacity(time, focusLane) * Math.min(1, laneA(l.lane))
      if (op < 0.01) {
        el.style.opacity = '0'
        return
      }
      v.copy(l.pos).project(camera)
      if (v.z > 1) {
        el.style.opacity = '0'
        return
      }
      const x = ((v.x + 1) / 2) * size.width
      const y = ((1 - v.y) / 2) * size.height
      el.style.opacity = String(op)
      el.style.transform = `translate3d(${x.toFixed(1)}px, ${y.toFixed(1)}px, 0) translate(-50%, -150%)`
    })
  })

  const hover = (e: ThreeEvent<PointerEvent>, row: number) => {
    e.stopPropagation()
    onHover({ row, x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY })
  }
  const dotRows = useMemo(() => {
    const rows = new Map<string, number>()
    for (let i = 0; i < data.positions.length / 3; i++) rows.set
    return rows
  }, [data])
  void dotRows

  return (
    <>
      <primitive object={cloud} onPointerMove={(e: ThreeEvent<PointerEvent>) => e.index !== undefined && hover(e, e.index)} onPointerOut={() => onHover(null)} />
      <primitive object={fan} />
      <primitive object={solid} />
      <primitive object={dashed} />
      <primitive object={cones} />
      <primitive object={overlay} />
    </>
  )
})

/* ------------------------------------------------------------------ shell -- */

export function DrkgScene({
  status,
  focusLane = null,
  onReveal,
  className,
}: {
  status: StageStatus
  focusLane?: number | null
  onReveal?: (revealed: number) => void
  className?: string
}) {
  const { data, error } = useDrkg()
  const reduce = useReducedMotion()
  const built = useMemo(() => (data ? build(data) : null), [data])
  const labelEls = useRef<(HTMLDivElement | null)[]>([])
  const [phase, setPhase] = useState('')
  const [replay, setReplay] = useState(0)
  const [hover, setHover] = useState<{ row: number; x: number; y: number } | null>(null)
  const [names, setNames] = useState<Record<string, string> | null>(null)

  const onHover = useCallback((h: { row: number; x: number; y: number } | null) => {
    setHover(h)
    if (h) loadNames().then(setNames, () => {})
  }, [])

  const meta = data?.scene.meta
  const variance = meta ? (meta.explainedVariance.reduce((a, b) => a + b, 0) * 100).toFixed(1) : null
  const legend = useMemo(() => {
    if (!data) return []
    const main = data.scene.types.filter((ty) => TYPE_COLORS[ty.name]).sort((a, b) => b.count - a.count).slice(0, 6)
    const rest = data.scene.types.filter((ty) => !main.includes(ty)).reduce((a, ty) => a + ty.count, 0)
    return [...main.map((ty) => ({ name: ty.name, count: ty.count, color: TYPE_COLORS[ty.name] })), ...(rest ? [{ name: 'Other', count: rest, color: OTHER_COLOR }] : [])]
  }, [data])

  const hoverType = hover && data ? data.scene.types[data.types[hover.row]]?.name : null
  const hoverName = hover ? (names?.[String(hover.row)] ?? null) : null

  return (
    <div
      className={cn('relative isolate overflow-hidden rounded-xl text-white ring-1 ring-black/10', className)}
      style={{ background: 'radial-gradient(120% 90% at 50% 40%, oklch(0.26 0.04 245) 0%, oklch(0.17 0.03 250) 60%, oklch(0.13 0.025 255) 100%)' }}
    >
      {built && data ? (
        <>
          <Canvas
            camera={{ position: [9, 7, 25], fov: 42, near: 0.1, far: 200 }}
            dpr={[1, 1.75]}
            gl={{ alpha: true, antialias: true }}
            raycaster={{ params: { Points: { threshold: 0.09 } } } as never}
            onPointerMissed={() => setHover(null)}
            aria-label="3D view of the DRKG embedding space with the stage 3 traversal"
          >
            <World
              data={data}
              built={built}
              status={status}
              reduce={reduce}
              focusLane={focusLane}
              replay={replay}
              labelEls={labelEls}
              onPhase={setPhase}
              onReveal={onReveal}
              onHover={onHover}
            />
          </Canvas>

          {/* projected labels; positioned per frame via transform */}
          <div className="pointer-events-none absolute inset-0 text-xs" aria-hidden>
            {built.labels.map((l, i) => (
              <div key={i} ref={(el) => void (labelEls.current[i] = el)} className="absolute top-0 left-0 whitespace-nowrap opacity-0 will-change-transform">
                {l.node}
              </div>
            ))}
          </div>

          {/* status chip */}
          <div className="pointer-events-none absolute top-3 left-3 flex max-w-[70%] items-center gap-2 rounded-full bg-white/8 px-3 py-1.5 text-xs text-white/90 ring-1 ring-white/12 backdrop-blur-md">
            {status === 'running' || (phase && !phase.startsWith('Done')) ? (
              <span className="relative flex size-2">
                <span className="absolute inline-flex size-full rounded-full bg-teal-300/70 motion-safe:animate-ping" />
                <span className="relative inline-flex size-2 rounded-full bg-teal-300" />
              </span>
            ) : (
              <span className="size-2 rounded-full bg-white/60" aria-hidden />
            )}
            <span className="truncate font-mono tabular-nums" role="status">{phase}</span>
          </div>

          <button
            type="button"
            onClick={() => setReplay((n) => n + 1)}
            className="absolute top-3 right-3 flex items-center gap-1.5 rounded-full bg-white/8 px-3 py-1.5 text-xs text-white/85 ring-1 ring-white/12 backdrop-blur-md transition-colors hover:bg-white/15 focus-visible:ring-2 focus-visible:ring-white/60 focus-visible:outline-none"
          >
            <RotateCcw className="size-3.5" aria-hidden /> Replay traversal
          </button>

          {/* legend: name + count, never colour alone */}
          <div className="pointer-events-none absolute bottom-3 left-3 rounded-lg bg-black/30 px-3 py-2 text-[11px] text-white/80 ring-1 ring-white/10 backdrop-blur-md">
            <p className="mb-1 text-white/55">{data.scene.meta.entities.toLocaleString()} DRKG entities</p>
            <ul className="grid grid-cols-2 gap-x-4 gap-y-0.5">
              {legend.map((l) => (
                <li key={l.name} className="flex items-center gap-1.5">
                  <span className="size-1.5 rounded-full" style={{ background: l.color }} aria-hidden />
                  <span>{l.name}</span>
                  <span className="ml-auto pl-2 font-mono text-white/50 tabular-nums">{l.count.toLocaleString()}</span>
                </li>
              ))}
            </ul>
            <div className="mt-1.5 flex gap-3 border-t border-white/10 pt-1.5 text-white/65">
              <span className="flex items-center gap-1.5"><span className="h-px w-4 bg-white/80" aria-hidden /> DRKG edge</span>
              <span className="flex items-center gap-1.5"><span className="w-4 border-t border-dashed border-white/80" aria-hidden /> vector / L2</span>
              <span className="flex items-center gap-1.5"><span className="size-2 rounded-full ring-1 ring-white/80" aria-hidden /> query</span>
            </div>
          </div>

          {/* honesty caption */}
          <p className="pointer-events-none absolute right-3 bottom-3 max-w-[46%] text-right text-[11px] leading-snug text-white/55">
            {meta?.projection ?? 'PCA-3'} projection of 400-d TransE ({variance}% variance) · distances are true 400-d L2
            <br />
            {meta?.formula}
          </p>

          {hover ? (
            <div
              className="pointer-events-none absolute z-10 rounded-md bg-black/70 px-2 py-1 text-xs text-white ring-1 ring-white/15"
              style={{ transform: `translate3d(${hover.x + 12}px, ${hover.y + 12}px, 0)`, top: 0, left: 0 }}
            >
              <p className="font-medium">{hoverName ?? (names ? `Row ${hover.row}` : '…')}</p>
              <p className="text-white/60">{hoverType}</p>
            </div>
          ) : null}
        </>
      ) : (
        <div className="flex h-full items-center justify-center gap-2 text-sm text-white/70">
          {error ? (
            <span>DRKG scene unavailable ({error}). Run frontend/scripts/drkg_scene.py.</span>
          ) : (
            <>
              <Loader2 className="size-4 animate-spin" aria-hidden /> Loading 97,238 DRKG embeddings…
            </>
          )}
        </div>
      )}
    </div>
  )
}

